import 'dart:async';

import 'package:core_visual_stream/core_visual_stream.dart';

import 'package:flutter/foundation.dart';
import 'package:flutter/widgets.dart';

import 'package:common_glasses_p2p/src/service/glasses_p2p_session.dart';

const _rtspPath = '/vs0?aspect_ratio=16_9&type=0';
const _rtspPort = 554;

/// [VisualStream] that drives the glasses Wi-Fi Direct → RTSP pipeline.
///
/// Connect flow:
/// 1. Send BLE `switchWifiP2p(open=true)` via [GlassesCommandSender].
/// 2. Wait for [GlassesWifiP2pEvent](success=true) on [eventStream] (15 s timeout).
/// 3. Call [GlassesP2pChannel.connectP2P(ssid)] → Group Owner IP.
/// 4. Connect inner RTSP preview to `rtsp://ip:554/vs0...`.
///
/// iOS Phase 1: [GlassesP2pChannel] throws [PlatformException] with code
/// `GLASSES_P2P_NOT_SUPPORTED` → falls back to [CameraVisualStream].
class GlassesP2pVisualStream implements VisualStream {
  GlassesP2pVisualStream({
    required GlassesP2pSession session,
  }) : _session = session;

  final GlassesP2pSession _session;
  final _eventController = StreamController<VisualStreamEvent>.broadcast();

  VisualStream? _inner;
  // Non-null while a connect() attempt is in flight.
  // Concurrent callers await the same Completer so they all unblock together
  // once the attempt completes (success or error).
  Completer<void>? _pendingConnect;
  // Tight timeout for the fast-path RTSP probe; fall back to full P2P if missed.
  static const _fastPathTimeout = Duration(seconds: 3);

  @override
  Stream<VisualStreamEvent> get events => _eventController.stream;

  @override
  Future<void> connect(VisualStreamConfig config) async {
    // Already connected — nothing to do.
    if (_inner != null) return;

    // Connection in flight — join the waiting list instead of starting another.
    if (_pendingConnect != null) {
      debugPrint('[GlassesP2P] connect: joining pending attempt');
      return _pendingConnect!.future;
    }

    final completer = Completer<void>();
    _pendingConnect = completer;
    _emit(const VisualStreamEvent.connecting());
    debugPrint('[GlassesP2P] connect start cachedIp=${_session.cachedHost}');
    try {
      await _connectInternal(config);
      completer.complete();
    } catch (e) {
      completer.completeError(e);
      rethrow;
    } finally {
      _pendingConnect = null;
    }
  }

  Future<void> _connectInternal(VisualStreamConfig config) async {
    // Fast path: P2P group from the previous session is still alive — try RTSP directly.
    // Saves the full ~5–15 s P2P handshake on reconnect.
    final cached = _session.cachedHost;
    if (cached != null) {
      try {
        await _connectRtsp(cached, timeout: _fastPathTimeout);
        debugPrint('[GlassesP2P] fast-path RTSP ok ip=$cached');
        return;
      } catch (e) {
        debugPrint(
          '[GlassesP2P] fast-path failed ($e), falling back to full P2P',
        );
        // Null out _inner before disconnecting it: RTSP player disconnect
        // disposes the platform view, so buildPreview() must stop returning it
        // (falling back to the placeholder) before that teardown runs, not after.
        final failed = _inner;
        _inner = null;
        await failed?.disconnect();
      }
    }

    try {
      final host = await _session.openPreview();
      if (host is Failure<String>) {
        _emit(
          VisualStreamEvent.error(
            message: host.error.message,
            errorCode: host.error.code,
          ),
        );
        return;
      }
      await _connectRtsp((host as Success<String>).value);
    } catch (e) {
      debugPrint('[GlassesP2P] unexpected error: $e');
      _emit(VisualStreamEvent.error(message: e.toString()));
    }
  }

  Future<void> _connectRtsp(String ip, {Duration? timeout}) async {
    final rtspUri = Uri.parse('rtsp://$ip:$_rtspPort$_rtspPath');
    debugPrint('[GlassesP2P] connecting RTSP $rtspUri timeout=$timeout');
    // fijkplayer_max/ijkplayer is tuned here for low-latency live RTSP.
    final inner = FijkVisualStream();
    _inner = inner;
    inner.events.listen(_emit);
    await inner.connect(
      VisualStreamConfig.url(
        rtspUri,
        connectTimeout: timeout ?? const Duration(seconds: 12),
      ),
    );
  }

  /// Nulls out [_inner] (and emits `disconnected`) before tearing it down.
  /// RTSP player disconnect disposes the platform view, so
  /// [buildPreview] must already be returning the placeholder — not the old
  /// widget — by the time that teardown actually runs, not after.
  Future<void> _disconnectInner() async {
    final inner = _inner;
    _inner = null;
    _emit(const VisualStreamEvent.disconnected());
    await inner?.disconnect();
  }

  @override
  Future<void> disconnect() async {
    debugPrint(
      '[GlassesP2P] disconnect (P2P group kept alive for fast reconnect)',
    );
    // Keep the Wi-Fi group alive during retry; page/app teardown must call
    // fullDisconnect() so the glasses stop the video stream and cool down.
    await _disconnectInner();
  }

  /// Releases both RTSP and the underlying P2P group.
  /// Call when leaving the preview page or when the glasses BLE session ends.
  Future<void> fullDisconnect() async {
    debugPrint('[GlassesP2P] fullDisconnect');
    await _disconnectInner();
    _session.scheduleClose(type: 2);
    _emit(const VisualStreamEvent.disconnected());
  }

  @override
  Widget buildPreview() {
    final inner = _inner;
    if (inner != null) return inner.buildPreview();
    return const ColoredBox(color: Color(0xFF111111));
  }

  @override
  Future<Uint8List> captureFrame() {
    final inner = _inner;
    if (inner == null) {
      return Future.error(
        const AppError(
          code: 'GLASSES_P2P_NOT_CONNECTED',
          message: 'No active stream to capture from',
        ),
      );
    }
    return inner.captureFrame();
  }

  void _emit(VisualStreamEvent event) {
    if (!_eventController.isClosed) _eventController.add(event);
  }

  Future<void> dispose() async {
    await fullDisconnect();
    await _eventController.close();
  }
}
