import 'package:core_base/core_base.dart';
import 'package:core_device_file_transfer/core_device_file_transfer.dart';

import 'glasses_p2p_session.dart';

/// 通过眼镜 Wi-Fi 文件通道导入照片和视频。
class GlassesP2pMediaTransferClient implements DeviceMediaTransferClient {
  /// 创建眼镜媒体导入客户端。
  GlassesP2pMediaTransferClient({
    required GlassesP2pSession session,
  }) : _session = session;

  final GlassesP2pSession _session;
  BkFtpDeviceMediaTransferClient? _client;

  @override
  Future<Result<void>> cancel(String taskId) async {
    return (_client ?? _ftpClient()).cancel(taskId);
  }

  @override
  Stream<DeviceMediaImportEvent> importRemoteMedia(
    DeviceMediaImportRequest request,
  ) async* {
    final ready = await _session.openFileTransfer();
    if (ready is Failure<String>) {
      yield DeviceMediaImportEvent(
        status: DeviceMediaImportStatus.failed,
        error: ready.error,
      );
      return;
    }
    try {
      yield* _ftpClient().importRemoteMedia(request);
    } finally {
      // ponytail: 3s 空闲超时，无新请求则关闭 P2P
      _session.scheduleClose(type: 1);
    }
  }

  @override
  Future<Result<List<DeviceMediaItem>>> localMedia(
    DeviceMediaTransferTarget target,
  ) {
    return (_client ?? _ftpClient()).localMedia(target);
  }

  @override
  Future<Result<DeviceRemoteMediaSummary>> remoteSummary(
    DeviceMediaTransferTarget target,
  ) async {
    if (_session.cachedHost == null) {
      return const Result.failure(
        AppError(
          code: 'media_transfer.wifi_not_ready',
          message: 'Device Wi-Fi file transfer is not ready',
        ),
      );
    }
    return _ftpClient().remoteSummary(target);
  }

  BkFtpDeviceMediaTransferClient _ftpClient() {
    return _client ??= BkFtpDeviceMediaTransferClient(
      configResolver: (_) async {
        final host = _session.cachedHost;
        return host == null ? null : DeviceMediaTransferFtpConfig(host: host);
      },
    );
  }
}
