import 'dart:async';
import 'dart:io';

import 'package:common_glasses_protocol/common_glasses_protocol.dart';
import 'package:core_base/core_base.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import 'glasses_p2p_channel.dart';

/// 眼镜 Wi-Fi/P2P 会话，统一管理连接、事件流和设备 IP 缓存。
class GlassesP2pSession {
  /// 创建眼镜 Wi-Fi/P2P 会话。
  GlassesP2pSession({
    required GlassesCommandSender commandSender,
    required Stream<GlassesEvent> eventStream,
    GlassesP2pChannel? channel,
  }) : _commandSender = commandSender,
       _eventStream = eventStream,
       _channel = channel ?? GlassesP2pChannel();

  final GlassesCommandSender _commandSender;
  final Stream<GlassesEvent> _eventStream;
  final GlassesP2pChannel _channel;

  String? _host;
  Completer<Result<String>>? _pendingOpen;
  Timer? _idleTimer;

  /// 当前缓存的设备 IP。
  String? get cachedHost => _host;

  /// 打开文件传输通道并返回设备 IP。
  Future<Result<String>> openFileTransfer() {
    return _open(type: 1);
  }

  /// 打开视频预览通道并返回设备 IP。
  Future<Result<String>> openPreview() {
    return _open(type: 2);
  }

  /// 关闭底层 Wi-Fi/P2P 通道。
  Future<void> close({int type = 2}) async {
    _idleTimer?.cancel();
    _idleTimer = null;
    _host = null;
    try {
      await _channel.disconnectP2P();
    } catch (_) {}
    if (Platform.isIOS) {
      await _commandSender.closeWifiAP();
    } else {
      await _commandSender.setWifiP2p(open: false, type: type);
    }
  }

  /// 在 [delay] 后关闭 P2P 通道；若期间有新连接请求则自动取消。
  ///
  /// 用于导入完成后的延迟断连：给用户切换到其他需要 P2P 的功能留出窗口，
  /// 避免眼镜 AP 刚关又立刻重开造成的重连延迟。
  void scheduleClose({
    Duration delay = const Duration(seconds: 3),
    int type = 1,
  }) {
    _idleTimer?.cancel();
    _idleTimer = Timer(delay, () => close(type: type));
  }

  Future<Result<String>> _open({required int type}) async {
    // 有新连接请求时取消待定的延迟关闭，复用现有连接。
    _idleTimer?.cancel();
    _idleTimer = null;
    final cached = _host;
    if (cached != null) {
      return Result.success(cached);
    }
    final pending = _pendingOpen;
    if (pending != null) {
      return pending.future;
    }

    final completer = Completer<Result<String>>();
    _pendingOpen = completer;
    try {
      final result = await _openInternal(type: type);
      completer.complete(result);
      return result;
    } catch (error) {
      final result = Result<String>.failure(
        AppError(
          code: 'glasses_p2p.open_failed',
          message: 'Failed to open glasses Wi-Fi connection',
          cause: error,
        ),
      );
      completer.complete(result);
      return result;
    } finally {
      _pendingOpen = null;
    }
  }

  Future<Result<String>> _openInternal({required int type}) async {
    final sw = Stopwatch()..start();

    // 先订阅事件流，再发唤醒指令，确保 BLE 事件不会在订阅前丢失。
    // ponytail: broadcast stream 无缓冲，订阅必须在发指令之前建立。
    final eventFuture = _eventStream
        .where((e) => e is GlassesWifiP2pEvent)
        .cast<GlassesWifiP2pEvent>()
        .first
        .timeout(const Duration(seconds: 15));

    final openResult = Platform.isIOS
        ? await _commandSender.openWifiAP()
        : await _commandSender.setWifiP2p(open: true, type: type);
    debugPrint('[P2P] wake cmd sent: ${sw.elapsedMilliseconds}ms');
    if (openResult is Failure<void>) {
      return Result.failure(openResult.error);
    }

    final GlassesWifiP2pEvent event;
    try {
      event = await eventFuture;
      debugPrint('[P2P] ble event: ${sw.elapsedMilliseconds}ms');
    } on TimeoutException {
      return const Result.failure(
        AppError(
          code: 'glasses_p2p.open_timeout',
          message: 'Timed out opening glasses Wi-Fi connection',
        ),
      );
    }

    if (!event.success || event.ssid.isEmpty) {
      return const Result.failure(
        AppError(
          code: 'glasses_p2p.open_rejected',
          message: 'Glasses rejected Wi-Fi connection request',
        ),
      );
    }

    final host = await _channel.connectP2P(
      event.ssid,
      password: event.password,
    );
    debugPrint('[P2P] connected: ${sw.elapsedMilliseconds}ms '
        'host=${host.trim().isEmpty ? "empty" : host}');
    if (host.trim().isEmpty) {
      return const Result.failure(
        AppError(
          code: 'glasses_p2p.empty_host',
          message: 'Glasses Wi-Fi connection returned an empty host',
        ),
      );
    }
    _host = host;
    return Result.success(host);
  }
}

/// 眼镜 Wi-Fi/P2P 会话 Provider。
final glassesP2pSessionProvider = Provider<GlassesP2pSession>((ref) {
  final eventsController = StreamController<GlassesEvent>.broadcast();
  ref.listen<AsyncValue<GlassesEvent>>(
    glassesDeviceEventsProvider,
    (_, next) => next.whenData(eventsController.add),
  );
  ref.onDispose(eventsController.close);
  return GlassesP2pSession(
    commandSender: ref.read(glassesCommandSenderProvider),
    eventStream: eventsController.stream,
  );
});
