    final l10n = DeviceAlbumL10n.of(context);
    final state = ref.watch(deviceAlbumControllerProvider);
    final controller = ref.read(deviceAlbumControllerProvider.notifier);
    ref.listen(
      deviceAlbumControllerProvider.select((state) => state.errorMessage),
      (_, message) {
        if (message != null && message.isNotEmpty) {
          AppToast.show(context, message);
        }
      },
    );

    return Scaffold(
      appBar: AppBar(title: Text(l10n.pageTitle)),
      body: RefreshIndicator(
        onRefresh: controller.load,
        child: CustomScrollView(
          slivers: [
            SliverToBoxAdapter(
              child: Padding(
                padding: EdgeInsets.all(tokens.spacingMd),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    _ImportPanel(l10n: l10n),
