  final DeviceMediaItem item;

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final controller = ref.read(deviceAlbumControllerProvider.notifier);
    final l10n = DeviceAlbumL10n.of(context);
    return InkWell(
      onTap: () {
        if (item.isPhoto) {
          Navigator.of(context).push(
            MaterialPageRoute<void>(
              fullscreenDialog: true,
              builder: (_) => _PhotoViewerPage(item: item),
            ),
          );
        } else if (item.isVideo) {
          Navigator.of(context).push(
            MaterialPageRoute<void>(
              fullscreenDialog: true,
              builder: (_) => _VideoPlayerPage(item: item),
            ),
          );
        }
      },
      onLongPress: () async {
        final confirmed = await showDialog<bool>(
          context: context,
          builder: (context) => AlertDialog(
            title: Text(l10n.deleteTitle),
            content: Text(l10n.deleteMessage),
            actions: [
              TextButton(
                onPressed: () => Navigator.of(context).pop(false),
                child: Text(l10n.cancel),
              ),
              FilledButton(
                onPressed: () => Navigator.of(context).pop(true),
                child: Text(l10n.delete),
              ),
            ],
          ),
        );
        if (confirmed == true) {
          await controller.hide(item);
        }
      },
      child: ClipRRect(
        borderRadius: BorderRadius.circular(8),
        child: Stack(
          fit: StackFit.expand,
          children: [
            if (item.isPhoto && File(item.localPath).existsSync())
              AppImage(
                source: AppImageSource.file(item.localPath),
                fit: BoxFit.cover,
              )
            else
              DecoratedBox(
                decoration: BoxDecoration(color: Colors.grey.shade300),
                child: Icon(
                  item.isVideo ? Icons.play_circle_fill : Icons.broken_image,
                ),
              ),
            if (item.isVideo)
              const Align(
                alignment: Alignment.center,
                child: Icon(Icons.play_circle_fill, color: Colors.white),
              ),
          ],
        ),
      ),
    );
  }
}

